import type { KsTooltip } from "../ks-tooltip/index";
import { RenderConfig } from "../ks-virtual-list/types";
export type Value = string | number;
export type CustomRenderFn<T> = (item: T, renderConfig?: RenderConfig) => HTMLElement | Element | number | string | unknown;
export type MenuItemPopoverProps<T> = Omit<KsTooltip & {
    render: CustomRenderFn<T>;
}, 'anchorEl' | 'close' | 'getContainer' | 'open' | 'visible' | 'defaultVisible' | 'trigger'>;
export interface DynamicSlotsConfig<T> {
    label?: string | CustomRenderFn<T>;
    prefix?: CustomRenderFn<T>;
    suffix?: CustomRenderFn<T>;
    description?: string | CustomRenderFn<T>;
    helpContent?: string | CustomRenderFn<T>;
    render?: CustomRenderFn<T>;
    popover?: Partial<MenuItemPopoverProps<T>>;
}
export interface MenuItemBase<T = MenuItemBase<unknown>> extends DynamicSlotsConfig<T> {
    value: Value;
    disabled?: boolean;
    selectable?: boolean;
    onClick?: (value: Value, event: PointerEvent) => void;
}
